function ActionModal({type,row,onClose,onSuccess,institutions=[],officers=[],bureaus=[],profile}:any){const [note,setNote]=useState(''),[status,setStatus]=useState(row?.status||'Pending'),[bureau,setBureau]=useState(''),[institutionId,setInstitutionId]=useState(''),[caseNumber,setCaseNumber]=useState(''),[category,setCategory]=useState(''),[subject,setSubject]=useState(''),[description,setDescription]=useState(''),[workflowType,setWorkflowType]=useState('transfer'),[targetOfficer,setTargetOfficer]=useState(''),[newBureau,setNewBureau]=useState(profile?.bureau_id||''),[receivedAt,setReceivedAt]=useState(new Date().toISOString().slice(0,10)),[expectedDisposal,setExpectedDisposal]=useState(''),[nextActionRequired,setNextActionRequired]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');const submit=async(e:any)=>{e.preventDefault();setError('');if(!supabase||(!row&&type!=='case')){setError('Supabase is not configured or a case was not selected.');return}if(type!=='case'&&note.trim().length<5){setError('Please provide a brief reason or action note (at least 5 characters).');return}setBusy(true);let result:any;if(type==='case'){const user=(await supabase.auth.getUser()).data.user;const complaint={case_number:caseNumber.trim(),institution_id:institutionId,category:category.trim()||null,subject:subject.trim()||null,description:description.trim()||null,received_at:new Date(`${receivedAt}T00:00:00`).toISOString(),expected_disposal_at:expectedDisposal||null,next_action_required:nextActionRequired.trim()||null,status:'Pending',bureau_id:profile?.is_admin?(newBureau||null):(profile?.bureau_id||null),created_by:user?.id};let result=await supabase.from('complaints').insert(complaint);let planningFieldsSaved=true;if(result.error&&missingPlanningColumns(result.error)){const legacyComplaint={...complaint};delete (legacyComplaint as any).expected_disposal_at;delete (legacyComplaint as any).next_action_required;result=await supabase.from('complaints').insert(legacyComplaint);planningFieldsSaved=false}if(result.error)setError(friendlyError(result.error));else onSuccess(planningFieldsSaved?'Complaint record created':'Complaint created. Apply migration 202610240003 to save next-action and expected-disposal fields.');setBusy(false);return}if(type==='action'||type==='assignment'){if(type==='assignment'&&!targetOfficer){setError('Select an active officer in the case Bureau/Cell.');setBusy(false);return}if(type==='assignment'){result=await supabase.rpc('assign_complaint_officer',{p_complaint_id:row.id,p_assigned_officer_id:targetOfficer,p_remarks:note.trim()})}else{const actorId=(await supabase.auth.getUser()).data.user?.id;result=await supabase.from('case_actions').insert({complaint_id:row.id,action_type:'update',remarks:note.trim(),status_after:status,actor_id:actorId})}}else{result=await supabase.from('transfers').insert({complaint_id:row.id,to_bureau_id:bureau||null,reason:note.trim(),transfer_type:workflowType,actor_id:(await supabase.auth.getUser()).data.user?.id})}if(result.error)setError(friendlyError(result.error));else onSuccess(type==='action'?'Action recorded':type==='assignment'?'Case assignment recorded':'Workflow request recorded');setBusy(false)};return <div className="modal-backdrop"><form className="modal" role="dialog" aria-modal="true" aria-label="Case workflow form" onSubmit={submit} onMouseDown={e=>e.stopPropagation()}><header><div><small>{type==='action'?'CASE WORKFLOW':type==='assignment'?'CASE ASSIGNMENT':'TRANSFER & ESCALATION'}</small><h2>{type==='action'?'Record an action':type==='case'?'Record a complaint':type==='assignment'?'Assign or reassign case':'Record transfer or escalation'}</h2></div><button type="button" className="icon-btn" onClick={onClose} aria-label="Close"><X size={18}/></button></header>{error&&<div className="form-error">{error}</div>}{type==='case'&&<>{profile?.is_admin&&<label>Bureau / Cell<select required value={newBureau} onChange={e=>setNewBureau(e.target.value)}><option value="">Select Bureau/Cell</option>{bureaus.map((b:any)=><option key={b.id} value={b.id}>{b.name}</option>)}</select></label>}<label>Case ID<input required minLength={3} value={caseNumber} onChange={e=>setCaseNumber(e.target.value)} placeholder="Enter the authorized case identifier"/></label><label>Date received<input type="date" required value={receivedAt} onChange={e=>setReceivedAt(e.target.value)}/></label><label>Expected disposal date<input type="date" value={expectedDisposal} onChange={e=>setExpectedDisposal(e.target.value)}/></label><label>Next action required<input value={nextActionRequired} onChange={e=>setNextActionRequired(e.target.value)} placeholder="Action or follow-up required"/></label><label>Institution<select required value={institutionId} onChange={e=>setInstitutionId(e.target.value)}><option value="">Select an institution</option>{institutions.map((i:any)=><option value={i.id} key={i.id}>{i.name} · {i.aicte_permanent_id||i.internal_id}</option>)}</select></label><label>Category<input value={category} onChange={e=>setCategory(e.target.value)} placeholder="Approved category"/></label><label>Subject<input required minLength={3} value={subject} onChange={e=>setSubject(e.target.value)} placeholder="Short complaint subject"/></label><label>Complaint description<textarea rows={7} value={description} onChange={e=>setDescription(e.target.value)} placeholder="Enter the complaint details, complainant information, previous actions, evidence, and requested resolution when available."/></label></>} {type==='assignment'&&<label>Active officer in this Bureau/Cell<select required value={targetOfficer} onChange={e=>setTargetOfficer(e.target.value)}><option value="">Choose an officer</option>{officers.filter((u:any)=>u.active&&u.bureau_id===row?.bureau_id&&['pgrc_officer','rb_officer','bureau_officer'].includes(u.role)).map((u:any)=><option key={u.id} value={u.id}>{u.display_name||u.id}</option>)}</select></label>}{type==='action'&&<label>Updated status<select value={status} onChange={e=>setStatus(e.target.value)}>{['Pending','Under Process','Disposed'].map(x=><option key={x}>{x}</option>)}</select></label>}{type!=='action'&&type!=='assignment'&&type!=='case'&&<><label>Workflow type<select value={workflowType} onChange={e=>setWorkflowType(e.target.value)}><option value="transfer">Transfer</option><option value="escalation">Escalation</option></select></label><label>Destination bureau ID (optional)<input value={bureau} onChange={e=>setBureau(e.target.value)} placeholder="UUID from configured bureaus"/></label></>}{type!=='case'&&<label>{type==='action'||type==='assignment'?'Action and remarks':'Reason'}<textarea required minLength={5} rows={4} value={note} onChange={e=>setNote(e.target.value)} placeholder="Describe the action taken and any follow-up…"/></label>}<p className="muted">{type==='case'?'Case records require an existing institution and an authorized case ID.':type==='assignment'?'Only a Bureau/Cell manager or administrator can assign cases; the database checks target scope.':'This action is attributed to your signed-in account and retained in the workflow history.'}</p><footer><button type="button" className="button subtle" onClick={onClose}>Cancel</button><button className="button primary" disabled={busy}>{busy?'Saving…':type==='case'?'Create authorized record':type==='assignment'?'Save assignment':'Confirm and save'}</button></footer></form></div>}
function useEscapeClose(onClose:()=>void){useEffect(()=>{const handleKeyDown=(event:KeyboardEvent)=>{if(event.key==='Escape')onClose()};document.addEventListener('keydown',handleKeyDown);return()=>document.removeEventListener('keydown',handleKeyDown)},[onClose])}
function exportCSV(cases:CaseRow[]){const columns=['case_number','institution','aicte_permanent_id','region','category','bureau','status','received_at','next_action_at','expected_disposal_at'];const escape=(v:unknown)=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};const lines=[columns.map(escape).join(','),...cases.map(c=>[c.case_number,c.institutions?.name,c.institutions?.aicte_permanent_id,c.institutions?.region,c.category,c.bureaus?.name,c.status,c.received_at,c.next_action_at,c.expected_disposal_at].map(escape).join(','))];const blob=new Blob([lines.join('\r\n')],{type:'text/csv;charset=utf-8'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='authorized-complaint-report.csv';link.click();URL.revokeObjectURL(link.href)}
